"""
Interactions during the process of Monaco Plan Creation
"""

from interops.libraries.squish_actions import CommonActions
import interops.libraries.desktop.decorators as deco
from interops.libraries.squish_actions.constants import MONACO_APP_NAME
from interops.libraries.monaco.interactions.objects.monaco_new_monaco_plan_objects import MonacoNewMonacoPlanObjects
from interops.libraries.monaco.interactions.objects.monaco_core_objects import MonacoCoreObjects


@deco.set_separate_app_context(MONACO_APP_NAME)
def prepare_plan_creation(study_id:str, image_set:str):
    """
    Steps to prepare the plan creation:
        Clicks specified Structure Set from Workspace > right-mouse on the specified Image Set > wait for the pop up menu
         > Clicks 'New Monaco Plan' from the context menu > wait for the New Monaco Plan window to show

    :params: study_id (str), Study ID
             image_set (str), Image Set
    """
    CommonActions.wait_for_object_exists(MonacoCoreObjects.workspace_Panel_Study_Tree, 20000)
    CommonActions.click_item(MonacoCoreObjects.workspace_Panel_Study_Tree, study_id)
    CommonActions.click_item(MonacoCoreObjects.workspace_Panel_Study_Tree, image_set, left_button=False)
    CommonActions.wait_for_object_to_appear(MonacoCoreObjects.new_Monaco_Plan_MenuItem, 8)
    CommonActions.left_click_object(MonacoCoreObjects.new_Monaco_Plan_MenuItem)
    CommonActions.wait_for_object_exists(MonacoNewMonacoPlanObjects.new_Monaco_Plan_Window,30000)

